import {
  Box,
  CardActionArea,
  CardContent,
  CardMedia,
  Container,
  Grid,
  Typography,
  Card,
  Divider,
} from "@mui/material";
import React from "react";
import blogImg from "../../../../assets/images/blogImg.png";
import CalendarMonthOutlinedIcon from "@mui/icons-material/CalendarMonthOutlined";
import { useNavigate } from "react-router-dom";
import "../../../../styles/animation.css";
import { useState } from "react";
import { useRef } from "react";
import { useEffect } from "react";
import { axiosInstance } from "src/network/adapter";
import { ApiEndpoints } from "src/network/endpoints";
import { toastError, toastSuccess } from "src/utils/utils";
import FallbackSpinner from "src/@core/components/spinner";

const OurBlogs = () => {
  const navigate = useNavigate();

  const [blogsData, setBlogsData] = useState([]);

  //animation
  const [visibleIndices, setVisibleIndices] = useState([]);
  const cardsRef = useRef([]);
  useEffect(() => {
    if (!blogsData.length) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const index = cardsRef.current.indexOf(entry.target);
            if (index !== -1 && !visibleIndices.includes(index)) {
              setVisibleIndices((prev) => [...prev, index]);
            }
          }
        });
      },
      { threshold: 0.1 }
    );

    cardsRef.current.forEach((card) => {
      if (card) {
        observer.observe(card);
      }
    });

    return () => {
      cardsRef.current.forEach((card) => {
        if (card) {
          observer.unobserve(card);
        }
      });
    };
  }, [blogsData, visibleIndices]);

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    const options = { year: "numeric", month: "short", day: "numeric" };
    return date.toLocaleDateString("en-US", options); // Adjust locale if needed
  };

  const fetchBlogsData = () => {
    axiosInstance
      .get(ApiEndpoints.BLOGS.list)
      .then((response) => {
        const responseData = response.data.data;
        const activeData = responseData.filter(
          (item) => item.status === "active"
        );
        setBlogsData(activeData);
      })
      .catch((error) => {
        toastError(error);
      });
  };
  useEffect(() => {
    fetchBlogsData();
  }, []);

  const handleBlogClick = (id) => {
    navigate(`/blog-details/${id}`);
  };
  return (
    <>
      <Box>
        <Container
          maxWidth={"xl"}
          sx={{
            px: { xs: 5, sm: 10, lg: 15, xl: 20 },
          }}
        >
          <Grid container rowGap={{ xs: 5, md: 12 }}>
            <Grid
              item
              xs={12}
              sx={{
                display: "flex",
                flexDirection: "column",
                gap: 3,
                alignItems: "center",
              }}
            >
              <Typography
                sx={{
                  fontSize: {
                    xs: "26px",
                    sm: "36px",
                    md: "46px",
                    lg: "56px",
                  },
                  fontWeight: 500,
                  lineHeight: {
                    xs: "40px",
                    sm: "50px",
                    md: "60px",
                    lg: "70px",
                  },
                  color: "#201D28",
                  textAlign: "center",
                }}
                className="fade-in-up-whoweare"
              >
                Our Blog: Tips, Trends, and Insights.
              </Typography>
              <Typography
                sx={{
                  fontSize: { xs: "14px", sm: "16px", lg: "18px" },
                  fontWeight: 500,
                  lineHeight: { xs: "26px", lg: "30px" },
                  color: "#646271",
                  textAlign: "center",
                }}
                className="fade-in-up-whoweare"
              >
                Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do
                eiusmod tempor incididunt ut labore
              </Typography>
            </Grid>
            <Grid item container xs={12} mt={5}>
              <Grid item xs={12} md={6}>
                <Typography
                  sx={{
                    fontSize: {
                      xs: "26px",
                      sm: "36px",
                      md: "46px",
                      lg: "56px",
                    },
                    fontWeight: 500,
                    lineHeight: {
                      xs: "34px",
                      sm: "50px",
                      md: "60px",
                      lg: "70px",
                    },
                    color: "#201D28",
                  }}
                  className="fade-in-up-whoweare"
                >
                  Read resources written by professionals.
                </Typography>
              </Grid>
              <Grid item xs={12} md={6}>
                {" "}
                <Typography
                  sx={{
                    fontSize: { xs: "14px", sm: "16px", lg: "18px" },
                    fontWeight: 500,
                    lineHeight: { xs: "26px", lg: "30px" },
                    color: "#646271",
                  }}
                  className="fade-in-up-whoweare"
                >
                  Lorem ipsum dolor sit amet, consectetur adipiscing elit.
                  Suspendisse varius enim in eros elementum tristique. Duis
                  cursus, mi quis viverra ornare, Lorem ipsum dolor sit amet,
                  consectetur adipiscing elit. Suspendisse varius enim in eros
                  elementum tristique. Duis cursus, mi quis viverra ornare,
                </Typography>
              </Grid>
            </Grid>
            <Grid item container rowGap={5} columnSpacing={5} xs={12}>
              {blogsData?.map((item, index) => (
                <Grid
                  item
                  xs={12}
                  md={4}
                  key={index}
                  ref={(el) => (cardsRef.current[index] = el)}
                  sx={{
                    opacity: visibleIndices.includes(index) ? 1 : 0,
                    transform: visibleIndices.includes(index)
                      ? "translateX(0)"
                      : "translateX(-30px)",
                    transition: "opacity 1s ease, transform 1s ease",
                    transitionDelay: visibleIndices.includes(index)
                      ? `${index * 0.5}s` // Staggered effect by index
                      : "0s",
                  }}
                >
                  <Card
                    sx={{
                      height: "100%",
                      borderRadius: "20px",
                      border: "1px solid #CACACA",
                      transition: "box-shadow 0.3s ease", // Smooth transition for hover effect
                      "&:hover": {
                        boxShadow: "0px 4px 12px #602DE1", // Box shadow on hover
                      },
                    }}
                  >
                    <CardActionArea onClick={() => handleBlogClick(item.id)}>
                      <CardMedia component="img" image={blogImg} />
                      <CardContent sx={{ p: 4 }}>
                        <Box
                          sx={{
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "space-between",
                          }}
                        >
                          <Typography
                            sx={{
                              fontSize: { xs: "14px", sm: "16px" },
                              lineHeight: { xs: "22px", sm: "24px" },
                              fontWeight: 500,
                              color: "#646271",
                            }}
                          >
                            {/* Web Development */}
                            {item?.category}
                          </Typography>
                          <Box
                            sx={{
                              display: "flex",
                              alignItems: "center",
                              gap: 2,
                            }}
                          >
                            <CalendarMonthOutlinedIcon
                              sx={{ color: "#646271" }}
                            />
                            <Typography
                              sx={{
                                fontSize: { xs: "14px", sm: "16px" },
                                lineHeight: { xs: "22px", sm: "24px" },
                                fontWeight: 500,
                                color: "#646271",
                              }}
                            >
                              {/* Oct 1, 2023 */}
                              {formatDate(item?.created_at)}
                            </Typography>
                          </Box>
                        </Box>
                        <Divider sx={{ color: "#CACACA" }} />
                        <Typography
                          sx={{
                            fontSize: { xs: "16px", md: "20px" },
                            lineHeight: { xs: "24px", md: "32px" },
                            fontWeight: 600,
                            color: "#201D28",
                          }}
                        >
                          {/* Lorem Ipsum dolore sit amet ipsum dolore Lorem Ipsum
                          dolore. */}
                          {item?.title}
                        </Typography>
                      </CardContent>
                    </CardActionArea>
                  </Card>
                </Grid>
              ))}
            </Grid>
          </Grid>
        </Container>
      </Box>
    </>
  );
};

export default OurBlogs;
